// HideSighting implements mm_usecase.adminRepository
func (mmHideSighting *AdminRepositoryMock) HideSighting(ctx context.Context, tx db.Executor, id string, hidden bool) (p1 models.PlateSighting, err error) {
	mm_atomic.AddUint64(&mmHideSighting.beforeHideSightingCounter, 1)
	defer mm_atomic.AddUint64(&mmHideSighting.afterHideSightingCounter, 1)

	mmHideSighting.t.Helper()

	if mmHideSighting.inspectFuncHideSighting != nil {
		mmHideSighting.inspectFuncHideSighting(ctx, tx, id, hidden)
	}

	mm_params := AdminRepositoryMockHideSightingParams{ctx, tx, id, hidden}

	// Record call args
	mmHideSighting.HideSightingMock.mutex.Lock()
	mmHideSighting.HideSightingMock.callArgs = append(mmHideSighting.HideSightingMock.callArgs, &mm_params)
	mmHideSighting.HideSightingMock.mutex.Unlock()

	for _, e := range mmHideSighting.HideSightingMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.p1, e.results.err
		}
	}

	if mmHideSighting.HideSightingMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmHideSighting.HideSightingMock.defaultExpectation.Counter, 1)
		mm_want := mmHideSighting.HideSightingMock.defaultExpectation.params
		mm_want_ptrs := mmHideSighting.HideSightingMock.defaultExpectation.paramPtrs

		mm_got := AdminRepositoryMockHideSightingParams{ctx, tx, id, hidden}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmHideSighting.t.Errorf("AdminRepositoryMock.HideSighting got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHideSighting.HideSightingMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.tx != nil && !minimock.Equal(*mm_want_ptrs.tx, mm_got.tx) {
				mmHideSighting.t.Errorf("AdminRepositoryMock.HideSighting got unexpected parameter tx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHideSighting.HideSightingMock.defaultExpectation.expectationOrigins.originTx, *mm_want_ptrs.tx, mm_got.tx, minimock.Diff(*mm_want_ptrs.tx, mm_got.tx))
			}

			if mm_want_ptrs.id != nil && !minimock.Equal(*mm_want_ptrs.id, mm_got.id) {
				mmHideSighting.t.Errorf("AdminRepositoryMock.HideSighting got unexpected parameter id, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHideSighting.HideSightingMock.defaultExpectation.expectationOrigins.originId, *mm_want_ptrs.id, mm_got.id, minimock.Diff(*mm_want_ptrs.id, mm_got.id))
			}

			if mm_want_ptrs.hidden != nil && !minimock.Equal(*mm_want_ptrs.hidden, mm_got.hidden) {
				mmHideSighting.t.Errorf("AdminRepositoryMock.HideSighting got unexpected parameter hidden, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHideSighting.HideSightingMock.defaultExpectation.expectationOrigins.originHidden, *mm_want_ptrs.hidden, mm_got.hidden, minimock.Diff(*mm_want_ptrs.hidden, mm_got.hidden))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmHideSighting.t.Errorf("AdminRepositoryMock.HideSighting got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmHideSighting.HideSightingMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmHideSighting.HideSightingMock.defaultExpectation.results
		if mm_results == nil {
			mmHideSighting.t.Fatal("No results are set for the AdminRepositoryMock.HideSighting")
		}
		return (*mm_results).p1, (*mm_results).err
	}
	if mmHideSighting.funcHideSighting != nil {
		return mmHideSighting.funcHideSighting(ctx, tx, id, hidden)
	}
	mmHideSighting.t.Fatalf("Unexpected call to AdminRepositoryMock.HideSighting. %v %v %v %v", ctx, tx, id, hidden)
	return
}

