// MinimockHideSightingDone returns true if the count of the HideSighting invocations corresponds
// the number of defined expectations
func (m *AdminRepositoryMock) MinimockHideSightingDone() bool {
	if m.HideSightingMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.HideSightingMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.HideSightingMock.invocationsDone()
}

// MinimockHideSightingInspect logs each unmet expectation
func (m *AdminRepositoryMock) MinimockHideSightingInspect() {
	for _, e := range m.HideSightingMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to AdminRepositoryMock.HideSighting at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterHideSightingCounter := mm_atomic.LoadUint64(&m.afterHideSightingCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.HideSightingMock.defaultExpectation != nil && afterHideSightingCounter < 1 {
		if m.HideSightingMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to AdminRepositoryMock.HideSighting at\n%s", m.HideSightingMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to AdminRepositoryMock.HideSighting at\n%s with params: %#v", m.HideSightingMock.defaultExpectation.expectationOrigins.origin, *m.HideSightingMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcHideSighting != nil && afterHideSightingCounter < 1 {
		m.t.Errorf("Expected call to AdminRepositoryMock.HideSighting at\n%s", m.funcHideSightingOrigin)
	}

	if !m.HideSightingMock.invocationsDone() && afterHideSightingCounter > 0 {
		m.t.Errorf("Expected %d calls to AdminRepositoryMock.HideSighting at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.HideSightingMock.expectedInvocations), m.HideSightingMock.expectedInvocationsOrigin, afterHideSightingCounter)
	}
}

